mapper.select:
SELECT type AS type, traded_at AS tradedAt, amount AS amount, balance_after AS balanceAfter
FROM cash_flow
WHERE company_id = #{companyId}
AND bank_name = #{bankName}
AND deleted_at IS NULL
AND (

    (type = #{r.type} AND traded_at = #{r.tradedAt} AND amount = #{r.amount} AND balance_after <=> #{r.balanceAfter})

)

mapper.update:
UPDATE cash_flow
SET settle_block_id = #{settleId}, linked_by = #{linkedBy}, linked_at = #{linkedAt}
WHERE cash_flow_id = #{cashFlowId} AND settle_block_id IS NULL AND deleted_at IS NULL

UPDATE settlement_block
SET status = #{status}, actual_amount = #{actualAmount}, actual_date = #{actualDate}
WHERE settle_id = #{settleId} AND status = 'PENDING'

UPDATE cash_flow
SET settle_block_id = NULL, linked_by = NULL, linked_at = NULL
WHERE cash_flow_id = #{cashFlowId}

UPDATE settlement_block
SET status = 'PENDING', actual_amount = NULL, actual_date = NULL
WHERE settle_id = #{settleId}

UPDATE cash_flow
SET bank_name = #{bankName}, traded_at = #{tradedAt}, type = #{type}, amount = #{amount},
depositor_name = #{depositorName}, bank_memo = #{memo}
WHERE cash_flow_id = #{cashFlowId}

UPDATE cash_flow SET is_excluded = #{isExcluded}
WHERE cash_flow_id IN

    #{id}
